#include <iostream>
#include <stdexcept>
#include <vector>
void replace(std::vector<int>& a, std::vector<int> b) {
    for (int x : b) if (x < 0) throw std::invalid_argument("negative");
    a.swap(b);
}
int main() {
    std::vector<int> a{100, 101};
    try { replace(a, {102, -1}); }
    catch (const std::invalid_argument&) { std::cout << a[0] << ' ' << a[1] << '\n'; }
    replace(a, {102, 103});
    std::cout << a[0] << ' ' << a[1] << '\n';
}
